  `❓ <b>Question:</b> ${escapedQuery}\n` +
  `📅 <b>Date:</b> ${new Date(timestamp).toLocaleString()}\n\n` +
  `━━━━━━━━━━━━━━━━━━━━━━━━━\n` +
  `Sending 5 responses...`;

const outputs = [];

// Header
outputs.push({
  json: {
    chatId: chatId,
    text: headerText,
    messageNumber: 1
  }
});

