const query = input.query;
const timestamp = input.timestamp;

// Create clean formatted text for Google Docs
const dateStr = new Date(timestamp).toLocaleString();

let docsContent = `━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n`;
docsContent += `📊 AI KNOWLEDGE LADDER RESULTS\n`;
docsContent += `━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n`;
docsContent += `❓ Question: ${query}\n`;
docsContent += `📅 Date: ${dateStr}\n\n`;
docsContent += `━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n`;

// Add each response with clean formatting
responses.forEach((r, index) => {
  const emoji = r.emoji || '❓';
  const title = r.title || 'Unknown';
  const content = r.content || 'No content';

  docsContent += `${emoji} ${title.toUpperCase()}\n`;
  docsContent += `${'─'.repeat(50)}\n\n`;
  docsContent += `${content}\n\n`;

  if (index < responses.length - 1) {
    docsContent += `\n`;
  }
});

docsContent += `\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n`;
docsContent += `End of Response\n`;
docsContent += `━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n\n`;

return [{
  json: {
    docsContent: docsContent
  }
}];
})();
return { body: __unwrap(__result) };
